<div class="page-heading"><a class="back" href="/admin">← All episodes</a><h1><?= empty($episode)?'Create an episode':'Episode studio' ?></h1><p>Tell your story. We’ll take care of the feeds.</p></div><div class="editor-grid"><div><form method="post" class="panel"><input type="hidden" name="csrf" value="<?= $escape($csrf) ?>"><h2>Episode details</h2><div class="field"><label for="title">Title</label><input id="title" name="title" required maxlength="300" value="<?= $escape($episode['title'] ?? '') ?>" placeholder="Give this episode a name"></div><div class="field"><label for="description">Show notes</label><textarea id="description" name="description" rows="8" maxlength="50000" placeholder="What will your listeners discover?"><?= $escape($episode['description'] ?? '') ?></textarea><small>Plain text. Required before publishing.</small></div><div class="columns"><div class="field"><label for="season">Season</label><input id="season" name="season" type="number" min="1" max="1000000" value="<?= $escape($episode['season'] ?? '') ?>"></div><div class="field"><label for="number">Episode number</label><input id="number" name="number" type="number" min="1" max="1000000" value="<?= $escape($episode['number'] ?? '') ?>"></div></div><div class="field"><label for="episode_type">Episode type</label><select id="episode_type" name="episode_type"><?php foreach (['full','trailer','bonus'] as $type): ?><option value="<?= $type ?>" <?= ($episode['episode_type'] ?? 'full')===$type?'selected':'' ?>><?= ucfirst($type) ?></option><?php endforeach ?></select></div><label class="check"><input type="checkbox" name="explicit" <?= !empty($episode['explicit'])?'checked':'' ?>> Contains explicit content</label><button type="submit"><?= empty($episode)?'Create draft & add media':'Save details' ?></button></form>
<?php require __DIR__.'/preview.php' ?>
<?php if ($episode): ?><section class="panel media-panel"><h2><?= $episode['audio_id']?'Replace media':'Add your media' ?></h2><p>Upload an MP3 for audio, or a MOV/MP4 for video and automatic MP3 extraction.</p><form id="upload-form" data-episode="<?= $escape($episode['id']) ?>"><div class="upload-area"><label for="media-file">Choose your episode file</label><input type="file" id="media-file" accept=".mp3,.mp4,.mov" required><small>Up to <?= round((int)(getenv('NEO_MAX_UPLOAD') ?: 10737418240)/1073741824,1) ?> GiB. Reselect the same file to resume an interrupted upload.</small></div><button type="submit" id="upload-button">Upload media</button><progress id="upload-progress" max="100" value="0" aria-label="Upload progress" hidden></progress><p id="upload-status" role="status" aria-live="polite"></p></form><?php if ($episode['state']==='published'): ?><p class="muted">Current media stays live until its replacement is ready.</p><?php endif ?></section><?php endif ?></div>
<aside><section class="panel"><h2>Publishing</h2><?php if (!$episode): ?><p>Save a draft to upload your media.</p><?php else: ?><span class="badge <?= $episode['state']==='published'?'success':'' ?>"><?= $escape(ucfirst($episode['state'])) ?></span><p id="processing-status" data-episode="<?= $escape($episode['id']) ?>" role="status"><?= $escape(ucfirst($jobs[0]['state'] ?? ($episode['audio_id']?'ready':'Waiting for media'))) ?></p><?php if (!empty($jobs[0]['error'])): ?><p class="notice"><?= $escape($jobs[0]['error']) ?></p><?php endif ?><p>Video episodes need a finished MP3 before publication. Both feeds update together.</p><div class="stack"><?php $active=false; foreach ($jobs as $job) { if (in_array($job['state'],['queued','processing','failed'],true)) { $active=true; } } ?><?php if ($episode['state']==='draft'): ?><form method="post" action="/admin/episodes/<?= $escape($episode['id']) ?>/publish"><input type="hidden" name="csrf" value="<?= $escape($csrf) ?>"><button type="submit" <?= !$episode['audio_id'] || $active || !$episode['description']?'disabled':'' ?>>Publish episode</button></form><?php else: ?><a href="/episodes/<?= $escape($episode['id']) ?>">View published episode →</a><form method="post" action="/admin/episodes/<?= $escape($episode['id']) ?>/unpublish"><input type="hidden" name="csrf" value="<?= $escape($csrf) ?>"><button type="submit" class="secondary">Revert to draft</button></form><?php endif ?><?php if (($jobs[0]['state'] ?? '')==='failed'): ?><form method="post" action="/admin/episodes/<?= $escape($episode['id']) ?>/retry"><input type="hidden" name="csrf" value="<?= $escape($csrf) ?>"><button type="submit" class="secondary">Retry processing</button></form><?php endif ?></div><hr><form method="post" data-confirm="Delete this episode? It will be removed from the website and both feeds." action="/admin/episodes/<?= $escape($episode['id']) ?>/delete"><input type="hidden" name="csrf" value="<?= $escape($csrf) ?>"><button class="danger" type="submit">Delete episode</button></form><?php endif ?></section><section class="panel aside"><h3>One upload. Two ways to tune in.</h3><p>Video stays in its original format. MP3 is created automatically for audio listeners, including Spotify.</p></section></aside></div>
